# Azure DevOps backlog creation for the Automated Data Engineering platform
# Generated by gen_ade_backlog.py from docs/plans/automated-data-engineering/
# Run on a machine where az + the azure-devops extension are installed and signed in.
# It CREATES work items (run once). To check first: az boards query --wiql "SELECT [System.Id] FROM workitems".
# NOT run as part of PR 1; import-ready file only.

$ErrorActionPreference = 'Stop'
# az.cmd path on Windows; falls back to 'az' on PATH.
$az = "C:\Program Files\Microsoft SDKs\Azure\CLI2\wbin\az.cmd"
if (-not (Test-Path $az)) { $az = "az" }
$ORG = "https://dev.azure.com/paulmalmquist1984"
$PROJECT = "Novendor"
& $az devops configure --defaults organization=$ORG project=$PROJECT

function New-WI($type, $title, $area, $iter, $tags, $desc, $ac, $parentId) {
  $args = @("boards","work-item","create","--type",$type,"--title",$title,
            "--area",$area,"--iteration",$iter,"--org",$ORG,"--project",$PROJECT,"--output","json")
  if ($desc) { $args += @("--description",$desc) }
  $fields = @()
  if ($tags) { $fields += "System.Tags=$tags" }
  if ($ac)   { $fields += "Microsoft.VSTS.Common.AcceptanceCriteria=$ac" }
  if ($fields.Count -gt 0) { $args += @("--fields") + $fields }
  $wi = & $az @args | ConvertFrom-Json
  if ($parentId) { & $az boards work-item relation add --id $wi.id --relation-type parent --target-id $parentId --org $ORG --yes | Out-Null }
  Write-Host ("  [{0}] #{1}  {2}" -f $type, $wi.id, $title)
  return $wi.id
}

Write-Host "== Ensuring area paths under $PROJECT\RS-Analytics (reused from RS-Analytics) =="
& $az boards area project create --name "RS-Analytics" --org $ORG --project $PROJECT 2>$null | Out-Null
& $az boards area project create --name "AgentPlatform" --path "\Novendor\Area\RS-Analytics" --org $ORG --project $PROJECT 2>$null | Out-Null
& $az boards area project create --name "DevOpsAutomation" --path "\Novendor\Area\RS-Analytics" --org $ORG --project $PROJECT 2>$null | Out-Null
& $az boards area project create --name "WinstonPrototype" --path "\Novendor\Area\RS-Analytics" --org $ORG --project $PROJECT 2>$null | Out-Null

Write-Host "== Creating iterations =="
& $az boards iteration project create --name "ADE PR1 - Governed fabric surface" --start-date 2026-06-12 --finish-date 2026-06-30 --org $ORG --project $PROJECT 2>$null | Out-Null
& $az boards iteration project create --name "ADE PR2+ - Provider abstraction & analytical engine" --start-date 2026-07-01 --finish-date 2026-12-31 --org $ORG --project $PROJECT 2>$null | Out-Null

Write-Host "== Creating work items =="

